#include <iostream>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    double c1x, c1y, c1r, c2x, c2y, c2r;
    cin >> c1x >> c1y >> c1r >> c2x >> c2y >> c2r;

    double dx = c2x - c1x;
    double dy = c2y - c1y;
    double d = sqrt(dx*dx + dy*dy);

    // Distance from c1 to the radical line
    double a = (d*d + c1r*c1r - c2r*c2r) / (2*d);
    double h = sqrt(c1r*c1r - a*a);

    // Midpoint
    double mx = c1x + a*dx/d;
    double my = c1y + a*dy/d;

    // Intersection points
    double p1x = mx + h*dy/d;
    double p1y = my - h*dx/d;
    double p2x = mx - h*dy/d;
    double p2y = my + h*dx/d;

    vector<pair<double,double>> pts;
    pts.push_back({p1x, p1y});
    pts.push_back({p2x, p2y});

    sort(pts.begin(), pts.end(), [](const pair<double,double>& a, const pair<double,double>& b){
        if (fabs(a.first - b.first) > 1e-9) return a.first < b.first;
        return a.second < b.second;
    });

    cout << fixed;
    cout.precision(10);
    cout << pts[0].first << " " << pts[0].second << endl;
    cout << pts[1].first << " " << pts[1].second << endl;

    return 0;
}

