using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double x1, y1, r1, x2, y2, r2;
    cin >> x1 >> y1 >> r1 >> x2 >> y2 >> r2;

    cout << fixed << setprecision(10);

    double dx = x2 - x1;
    double dy = y2 - y1;
    double d = hypot(dx, dy);

    if (d > r1 + r2 + 1e-9 || d < fabs(r1 - r2) - 1e-9) {
        // No intersection
        return 0;
    }

    // Distance from c1 to the line connecting intersection points
    double a = (r1*r1 - r2*r2 + d*d) / (2*d);
    double h2 = r1*r1 - a*a;
    if (h2 < 0) h2 = 0;
    double h = sqrt(h2);

    // Midpoint of the chord
    double mx = x1 + a * dx / d;
    double my = y1 + a * dy / d;

    // Offset from midpoint to intersection points
    double rx = -dy * (h / d);
    double ry = dx * (h / d);

    double i1x = mx + rx, i1y = my + ry;
    double i2x = mx - rx, i2y = my - ry;

    // Sort by x, then y
    if (i1x > i2x + 1e-12 || (fabs(i1x - i2x) < 1e-12 && i1y > i2y + 1e-12)) {
        swap(i1x, i2x);
        swap(i1y, i2y);
    }

    cout << i1x << " " << i1y << "\n";
    cout << i2x << " " << i2y << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double x1, y1, r1, x2, y2, r2;
    cin >> x1 >> y1 >> r1 >> x2 >> y2 >> r2;

    const double EPS = 1e-12;

    double dx = x2 - x1, dy = y2 - y1;
    double d = hypot(dx, dy);

    // Unit vector from center1 to center2
    double ex = dx / d, ey = dy / d;

    // Distance from center1 to the projection point on the line between centers
    double a = (r1 * r1 - r2 * r2 + d * d) / (2.0 * d);

    // Height from projection point to intersection points
    double h2 = r1 * r1 - a * a;
    if (h2 < 0 && h2 > -EPS) h2 = 0;
    double h = sqrt(max(0.0, h2));

    // Base point
    double px = x1 + a * ex;
    double py = y1 + a * ey;

    // Perpendicular vector
    double rx = -ey * h;
    double ry = ex * h;

    double ix1 = px + rx;
    double iy1 = py + ry;
    double ix2 = px - rx;
    double iy2 = py - ry;

    if (ix2 < ix1 - EPS || (fabs(ix1 - ix2) <= EPS && iy2 < iy1)) {
        swap(ix1, ix2);
        swap(iy1, iy2);
    }

    cout << fixed << setprecision(10);
    cout << ix1 << ' ' << iy1 << '\n';
    cout << ix2 << ' ' << iy2 << '\n';

    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double x1, y1, r1, x2, y2, r2;
    scanf("%lf %lf %lf %lf %lf %lf", &x1, &y1, &r1, &x2, &y2, &r2);

    double dx = x2 - x1;
    double dy = y2 - y1;
    double d = sqrt(dx*dx + dy*dy);

    // No intersection
    if (d > r1 + r2 + 1e-12 || d < fabs(r1 - r2) - 1e-12) {
        // Should not happen per problem statement, but handle gracefully
        return 0;
    }

    // One or two intersections
    double a = (r1*r1 - r2*r2 + d*d) / (2.0 * d);
    double h2 = r1*r1 - a*a;
    if (h2 < 0) h2 = 0; // numerical stability
    double h = sqrt(h2);

    double xm = x1 + a * dx / d;
    double ym = y1 + a * dy / d;

    double xs1, ys1, xs2, ys2;

    if (h < 1e-12) {
        // Tangent - one intersection point
        xs1 = xs2 = xm;
        ys1 = ys2 = ym;
    } else {
        double rx = -dy * (h / d);
        double ry = dx * (h / d);
        xs1 = xm + rx;
        ys1 = ym + ry;
        xs2 = xm - rx;
        ys2 = ym - ry;
    }

    // Sort by x then y
    if (xs1 > xs2 + 1e-12 || (fabs(xs1 - xs2) < 1e-12 && ys1 > ys2 + 1e-12)) {
        double temp;
        temp = xs1; xs1 = xs2; xs2 = temp;
        temp = ys1; ys1 = ys2; ys2 = temp;
    }

    printf("%.10f %.10f\n", xs1, ys1);
    printf("%.10f %.10f\n", xs2, ys2);

    return 0;
}

