int main() {
    double c1x, c1y, c1r, c2x, c2y, c2r;
    scanf("%lf %lf %lf", &c1x, &c1y, &c1r);
    scanf("%lf %lf %lf", &c2x, &c2y, &c2r);

    double dx = c2x - c1x;
    double dy = c2y - c1y;
    double d = sqrt(dx*dx + dy*dy);

    double a = (c1r*c1r - c2r*c2r + d*d) / (2.0 * d);
    double h2 = c1r*c1r - a*a;
    if (h2 < 0) h2 = 0;
    double h = sqrt(h2);

    // Point P
    double px = c1x + a * dx / d;
    double py = c1y + a * dy / d;

    // Two intersection points
    double x1 = px + h * dy / d;
    double y1 = py - h * dx / d;
    double x2 = px - h * dy / d;
    double y2 = py + h * dx / d;

    // Order: smaller x first, tie -> smaller y first
    if (x1 > x2 + 1e-9 || (fabs(x1 - x2) < 1e-9 && y1 > y2 + 1e-9)) {
        // swap
        double tmp;
        tmp = x1; x1 = x2; x2 = tmp;
        tmp = y1; y1 = y2; y2 = tmp;
    }

    printf("%.10f %.10f\n%.10f %.10f\n", x1, y1, x2, y2);

    return 0;
}

#include <stdio.h>
