int main(void) {
    double x0, y0, r0;
    double x1, y1, r1;

    if (scanf("%lf %lf %lf", &x0, &y0, &r0) != 3) return 0;
    if (scanf("%lf %lf %lf", &x1, &y1, &r1) != 3) return 0;

    double dx = x1 - x0;
    double dy = y1 - y0;
    double d = sqrt(dx * dx + dy * dy);

    /* Distance from center 0 to the line through intersection points */
    double a = (r0 * r0 - r1 * r1 + d * d) / (2.0 * d);

    /* Midpoint on the line between centers */
    double xm = x0 + a * dx / d;
    double ym = y0 + a * dy / d;

    /* Distance from midpoint to each intersection point */
    double h2 = r0 * r0 - a * a;
    if (h2 < 0 && h2 > -1e-12) h2 = 0; /* avoid negative due to precision */
    double h = sqrt(h2);

    /* Perpendicular offset */
    double rx = -dy * (h / d);
    double ry =  dx * (h / d);

    double ix1 = xm + rx;
    double iy1 = ym + ry;
    double ix2 = xm - rx;
    double iy2 = ym - ry;

    /* Sort: smaller x first, then smaller y */
    if (ix1 > ix2 || (fabs(ix1 - ix2) < 1e-12 && iy1 > iy2)) {
        double tx = ix1, ty = iy1;
        ix1 = ix2; iy1 = iy2;
        ix2 = tx;  iy2 = ty;
    }

    printf("%.10f %.10f\n", ix1, iy1);
    printf("%.10f %.10f\n", ix2, iy2);

    return 0;
}

