import java.util.Scanner;

public class CircleIntersection {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x1 = sc.nextDouble();
        double y1 = sc.nextDouble();
        double r1 = sc.nextDouble();
        double x2 = sc.nextDouble();
        double y2 = sc.nextDouble();
        double r2 = sc.nextDouble();
        sc.close();

        double dx = x2 - x1;
        double dy = y2 - y1;
        double d = Math.sqrt(dx * dx + dy * dy);

        // No intersection
        if (d > r1 + r2 + 1e-12 || d < Math.abs(r1 - r2) - 1e-12 || (d == 0 && r1 != r2)) {
            // No intersection points, but per problem we shouldn't get this case.
            return;
        }

        // One intersection (externally or internally tangent)
        if (Math.abs(d - (r1 + r2)) < 1e-12) {
            double t = r1 / (r1 + r2);
            double ix = x1 + t * dx;
            double iy = y1 + t * dy;
            System.out.printf("%.10f %.10f%n", ix, iy);
            System.out.printf("%.10f %.10f%n", ix, iy);
            return;
        }
        if (Math.abs(d - Math.abs(r1 - r2)) < 1e-12) {
            double t;
            if (r1 > r2) {
                t = r1 / (r1 - r2);
            } else {
                t = r1 / (r1 - r2);
            }
            double ix = x1 + t * dx;
            double iy = y1 + t * dy;
            System.out.printf("%.10f %.10f%n", ix, iy);
            System.out.printf("%.10f %.10f%n", ix, iy);
            return;
        }

        // Two intersections
        double a = (r1 * r1 - r2 * r2 + d * d) / (2 * d);
        double h = Math.sqrt(r1 * r1 - a * a);

        double xm = x1 + a * dx / d;
        double ym = y1 + a * dy / d;

        double xs1 = xm + h * dy / d;
        double ys1 = ym - h * dx / d;
        double xs2 = xm - h * dy / d;
        double ys2 = ym + h * dx / d;

        // Sort by x, then y
        if (xs1 > xs2 || (Math.abs(xs1 - xs2) < 1e-12 && ys1 > ys2)) {
            double tmpX = xs1; double tmpY = ys1;
            xs1 = xs2; ys1 = ys2;
            xs2 = tmpX; ys2 = tmpY;
        }

        System.out.printf("%.10f %.10f%n", xs1, ys1);
        System.out.printf("%.10f %.10f%n", xs2, ys2);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        double x1 = fs.nextDouble();
        double y1 = fs.nextDouble();
        double r1 = fs.nextDouble();

        double x2 = fs.nextDouble();
        double y2 = fs.nextDouble();
        double r2 = fs.nextDouble();

        double dx = x2 - x1;
        double dy = y2 - y1;
        double d = Math.hypot(dx, dy);

        // Point on the line between centers where the chord crosses
        double a = (r1 * r1 - r2 * r2 + d * d) / (2.0 * d);
        double px = x1 + a * dx / d;
        double py = y1 + a * dy / d;

        double h2 = r1 * r1 - a * a;
        if (h2 < 0 && h2 > -1e-12) h2 = 0; // numerical safety
        double h = Math.sqrt(Math.max(0.0, h2));

        // Perpendicular vector
        double rx = -dy * (h / d);
        double ry = dx * (h / d);

        double ix1 = px + rx;
        double iy1 = py + ry;
        double ix2 = px - rx;
        double iy2 = py - ry;

        // Sort lexicographically: smaller x first, then smaller y
        if (ix1 > ix2 || (Math.abs(ix1 - ix2) < 1e-12 && iy1 > iy2)) {
            double tx = ix1, ty = iy1;
            ix1 = ix2; iy1 = iy2;
            ix2 = tx;  iy2 = ty;
        }

        System.out.printf(Locale.US, "%.10f %.10f %.10f %.10f%n", ix1, iy1, ix2, iy2);
    }
}
